  function planAdoptionSchedule(
    input: AdoptionSchedulePlanInput
  ): AdoptionSchedulePlanOutput {
    const {
      participantList,
      minimumPreparationDaysInBusinessDays,
      targetAdoptionStartDate,
      executorUserId,
    } = input;
  
    // Check executor permission
    const permissionResult = judgeAccessPermission({
      userId: executorUserId,
      resourceType: "dashboard",
      operation: "edit",
    } as any);
  
    if (!permissionResult.isPermitted) {
      throw new Error("導入計画策定の実行権限がありません");
    }
  
    // Validate required roles
    const requiredRoles = ["部長", "PM", "エンジニア代表"];
    const providedRoles = participantList.map((p) => p.role);
    const hasAllRequiredRoles = requiredRoles.every((role) =>
      providedRoles.includes(role)
    );
  
    if (!hasAllRequiredRoles) {
      throw new Error("必須役割が不足しています");
    }
  
    // Validate preparation days range
    if (
      minimumPreparationDaysInBusinessDays < 1 ||
      minimumPreparationDaysInBusinessDays > 30
    ) {
      throw new Error("準備期間は1～30営業日の範囲で指定してください");
    }
  
    // Calculate preparation end date by subtracting business days
    const adoptionStart = new Date(targetAdoptionStartDate);
    let currentDate = new Date(adoptionStart);
    let businessDaysToSubtract = minimumPreparationDaysInBusinessDays;
  
    while (businessDaysToSubtract > 0) {
      currentDate.setDate(currentDate.getDate() - 1);
      const dayOfWeek = currentDate.getDay();
      // Skip weekends (0 = Sunday, 6 = Saturday)
      if (dayOfWeek !== 0 && dayOfWeek !== 6) {
        businessDaysToSubtract--;
      }
    }
  
    const calculatedPreparationEndDate = currentDate
      .toISOString()
      .split("T")[0];
  
    // Generate milestones
    const milestones: Array<{
      milestoneName: string;
      scheduledDate: string;
      targetParticipantRoles: string[];
    }> = [];
  
    const prepEndDate = new Date(calculatedPreparationEndDate);
    
  
    // Milestone 1: ガイド作成 (at preparation end date)
    milestones.push({
      milestoneName: "ガイド作成",
      scheduledDate: calculatedPreparationEndDate,
      targetParticipantRoles: ["PM"],
    });
  
    // Milestone 2: 部長研修 (2 business days after prep end)
    let managerTrainingDate = new Date(prepEndDate);
    let daysAdded = 0;
    while (daysAdded < 2) {
      managerTrainingDate.setDate(managerTrainingDate.getDate() + 1);
      const dayOfWeek = managerTrainingDate.getDay();
      if (dayOfWeek !== 0 && dayOfWeek !== 6) {
        daysAdded++;
      }
    }
    milestones.push({
      milestoneName: "部長研修",
      scheduledDate: managerTrainingDate.toISOString().split("T")[0],
      targetParticipantRoles: ["部長"],
    });
  
    // Milestone 3: 全員研修 (4 business days after prep end)
    let engineerTrainingDate = new Date(prepEndDate);
    daysAdded = 0;
    while (daysAdded < 4) {
      engineerTrainingDate.setDate(engineerTrainingDate.getDate() + 1);
      const dayOfWeek = engineerTrainingDate.getDay();
      if (dayOfWeek !== 0 && dayOfWeek !== 6) {
        daysAdded++;
      }
    }
    milestones.push({
      milestoneName: "全員研修",
      scheduledDate: engineerTrainingDate.toISOString().split("T")[0],
      targetParticipantRoles: ["部長", "PM", "エンジニア代表"],
    });
  
    // Milestone 4: 初回テスト報告 (6 business days after prep end)
    let initialReportDate = new Date(prepEndDate);
    daysAdded = 0;
    while (daysAdded < 6) {
      initialReportDate.setDate(initialReportDate.getDate() + 1);
      const dayOfWeek = initialReportDate.getDay();
      if (dayOfWeek !== 0 && dayOfWeek !== 6) {
        daysAdded++;
      }
    }
    milestones.push({
      milestoneName: "初回テスト報告",
      scheduledDate: initialReportDate.toISOString().split("T")[0],
      targetParticipantRoles: ["エンジニア代表"],
    });
  
    // Milestone 5: 本運用開始 (adoption start date)
    milestones.push({
      milestoneName: "本運用開始",
      scheduledDate: targetAdoptionStartDate,
      targetParticipantRoles: ["部長", "PM", "エンジニア代表"],
    });
  
    const scheduleId = `schedule_${randomUUID()}`;
  
    return {
      scheduleId,
      confirmedParticipants: participantList,
      calculatedPreparationEndDate,
      adoptionStartDate: targetAdoptionStartDate,
      milestones: milestones.map((m) => ({
        milestoneName: m.milestoneName,
        scheduledDate: m.scheduledDate,
        targetParticipantRoles: m.targetParticipantRoles,
      })),
    };
  }
