/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateInitialReportSubmission exports=evaluateInitialReportSubmission */
const __aivicBundle_5_evaluateInitialReportSubmission = (() => {
  function evaluateInitialReportSubmission(
    input: any,
    morningMeetingStartTime?: Date
  ): InitialReportEvaluationResult {
    // Handle both single object and 7-argument forms
    let reportId: string;
    let engineerId: string;
    let yesterdayAccomplishment: string;
    let todayPlan: string;
    let issuesAndConcerns: string;
    let submissionTimestamp: Date;
    let trainingPhaseId: string;
  
    if (typeof input === "object" && input !== null && !Array.isArray(input)) {
      // Object form
      reportId = input.reportId;
      engineerId = input.engineerId;
      yesterdayAccomplishment = input.yesterdayAccomplishment;
      todayPlan = input.todayPlan;
      issuesAndConcerns = input.issuesAndConcerns;
      submissionTimestamp = input.submissionTimestamp;
      trainingPhaseId = input.trainingPhaseId;
    } else {
      // 7-argument form (input is reportId, morningMeetingStartTime is engineerId, etc.)
      reportId = input;
      engineerId = morningMeetingStartTime as any;
      yesterdayAccomplishment = arguments[2];
      todayPlan = arguments[3];
      issuesAndConcerns = arguments[4];
      submissionTimestamp = arguments[5];
      trainingPhaseId = arguments[6];
    }
  
    // Check for null reportData
    if (input && typeof input === "object" && input.reportData === null) {
      throw new Error("報告データが見つかりません");
    }
  
    // Validate required fields
    if (
      !yesterdayAccomplishment ||
      yesterdayAccomplishment.trim().length === 0
    ) {
      throw new Error("必須項目（昨日の実績）が入力されていません");
    }
    if (!todayPlan || todayPlan.trim().length === 0) {
      throw new Error("必須項目（本日の予定）が入力されていません");
    }
    if (!issuesAndConcerns || issuesAndConcerns.trim().length === 0) {
      throw new Error("必須項目（課題・懸念事項）が入力されていません");
    }
  
    // Check for invalid characters (script tags, control characters)
    const invalidPatterns = /<script|<\/script|javascript:|onerror=|onload=/i;
    if (
      invalidPatterns.test(yesterdayAccomplishment) ||
      invalidPatterns.test(todayPlan) ||
      invalidPatterns.test(issuesAndConcerns)
    ) {
      throw new Error("入力形式が不正です。スクリプトタグは使用できません");
    }
  
    // Check for minimum character length constraint
    const minCharLength = 10;
    const feedbackItems: Array<{
      fieldName: string;
      evaluationLevel: "GOOD" | "FAIR" | "POOR";
      improvementInstruction: string;
    }> = [];
  
    if (yesterdayAccomplishment.length < minCharLength) {
      feedbackItems.push({
        fieldName: "昨日の実績",
        evaluationLevel: "POOR",
        improvementInstruction: `昨日の実績は${minCharLength}文字以上で記入してください。現在: ${yesterdayAccomplishment.length}文字`,
      });
    }
  
    if (todayPlan.length < minCharLength) {
      feedbackItems.push({
        fieldName: "本日の予定",
        evaluationLevel: "POOR",
        improvementInstruction: `本日の予定は${minCharLength}文字以上で記入してください。現在: ${todayPlan.length}文字`,
      });
    }
  
    if (issuesAndConcerns.length < minCharLength) {
      feedbackItems.push({
        fieldName: "課題・懸念事項",
        evaluationLevel: "POOR",
        improvementInstruction: `課題・懸念事項は${minCharLength}文字以上で記入してください。報告内容が非常に短い場合は、より詳細な説明を追加してください。現在: ${issuesAndConcerns.length}文字`,
      });
    }
  
    // Check for late submission (after 30 minutes past morning meeting start time)
    if (morningMeetingStartTime) {
      const thirtyMinutesAfterMeeting = new Date(
        morningMeetingStartTime.getTime() + 30 * 60 * 1000
      );
      if (submissionTimestamp > thirtyMinutesAfterMeeting) {
        feedbackItems.push({
          fieldName: "提出時刻",
          evaluationLevel: "FAIR",
          improvementInstruction:
            "朝会開始予定時刻の30分以内に報告を提出してください。定時報告期限を超過しています",
        });
      }
    }
  
    // Calculate quality score based on content length and completeness
    const totalLength =
      yesterdayAccomplishment.length +
      todayPlan.length +
      issuesAndConcerns.length;
    const avgLength = totalLength / 3;
  
    let qualityScore = 0;
    let formatUnificationDegree = 0;
  
    if (feedbackItems.length === 0) {
      // All fields meet minimum requirements
      qualityScore = Math.min(100, 50 + Math.floor(avgLength / 5));
      qualityScore = Math.max(80, qualityScore);
      formatUnificationDegree = 100;
    } else if (feedbackItems.length === 1) {
      // One field is short or late submission
      qualityScore = Math.floor(avgLength / 2);
      formatUnificationDegree = 70;
    } else if (feedbackItems.length === 2) {
      // Two fields are short
      qualityScore = Math.floor(avgLength / 3);
      formatUnificationDegree = 50;
    } else {
      // All three fields are short
      qualityScore = 25;
      formatUnificationDegree = 30;
    }
  
    const evaluationStatus = qualityScore >= 80 ? "PASSED" : "FAILED";
  
    if (evaluationStatus === "FAILED" && feedbackItems.length === 0) {
      throw new Error("品質スコアが基準値未満です");
    }
  
    return {
      reportId,
      evaluationStatus,
      qualityScore,
      formatUnificationDegree,
      feedbackItems,
      evaluationTimestamp: new Date(),
    };
  }
  return { evaluateInitialReportSubmission };
})();
