/* AIVIC_FUNCTION_BUNDLE_START owner=calculateOperationSkillScore exports=calculateOperationSkillScore */
const __aivicBundle_7_calculateOperationSkillScore = (() => {
  function calculateOperationSkillScore(
    input: OperationSkillAssessmentInput
  ): OperationSkillScoreResult {
    const {
      engineerId,
      initialReportData,
      trainingCompletionDate,
      evaluationCriteria,
    } = input;
  
    // 操作ステップ完了度スコア（0～40点）
    // 最大ステップ数を12と仮定し、完了ステップ数に基づいて計算
    const maxOperationSteps = 12;
    const operationCompletionScore = Math.min(
      40,
      (initialReportData.operationStepsCompleted / maxOperationSteps) * 40
    );
  
    // エラー対応能力スコア（0～30点）
    // エラー発生数が少ないほど高スコア。最大許容エラー数を5と仮定
    const maxAllowedErrors = 5;
    const errorManagementScore = Math.max(
      0,
      30 - (initialReportData.errorOccurrenceCount / maxAllowedErrors) * 30
    );
  
    // 報告形式準拠度スコア（0～30点）
    // validateInitialReportQuality を呼び出して形式準拠度を取得
    const validationInput: InitialReportValidationInput = {
      reportId: initialReportData.reportId,
      engineerId: engineerId,
      reportContent: {
        yesterdayAccomplishment: "",
        todayPlan: "",
        issueKeywords: [],
        issueDescription: "",
      },
      trainingCompletionDate: new Date(trainingCompletionDate),
      validationContext: {
        teamId: "",
        minimumQualityScoreThreshold: 0,
        requiredKeywordCount: 0,
        minimumIssueDescriptionLength: 0,
      },
    };
  
    const validationResult = validateInitialReportQuality(validationInput);
    const formatComplianceScore = Math.min(
      30,
      (validationResult.formatComplianceScore / 100) * 30
    );
  
    // 総合スコア計算（0～100点）
    const totalSkillScore = Math.round(
      operationCompletionScore + errorManagementScore + formatComplianceScore
    );
  
    // 合格判定（デフォルト70点以上）
    const passingScore = evaluationCriteria?.passingScore ?? 70;
    const passJudgment = totalSkillScore >= passingScore;
  
    return {
      engineerId,
      skillScore: totalSkillScore,
      passJudgment,
      scoreBreakdown: {
        operationCompletionScore: Math.round(operationCompletionScore),
        errorManagementScore: Math.round(errorManagementScore),
        formatComplianceScore: Math.round(formatComplianceScore),
      },
    };
  }
  return { calculateOperationSkillScore };
})();
export const calculateOperationSkillScore = __aivicBundle_7_calculateOperationSkillScore.calculateOperationSkillScore;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateOperationSkillScore */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateInitialReportQuality exports=validateInitialReportQuality */
const __aivicBundle_8_validateInitialReportQuality = (() => {
  function validateInitialReportQuality(
    input: InitialReportValidationInput
  ): InitialReportValidationResult {
    const {
      reportId,
      engineerId,
      reportContent,
      trainingCompletionDate,
      validationContext,
    } = input;
  
    const {
      teamId,
      minimumQualityScoreThreshold,
      requiredKeywordCount,
      minimumIssueDescriptionLength,
    } = validationContext;
  
    // 必須項目の検証
    const requiredFieldsCheckResult: FieldValidationResult = {
      isValid:
        reportContent.yesterdayAccomplishment &&
        reportContent.yesterdayAccomplishment.trim().length > 0 &&
        reportContent.todayPlan &&
        reportContent.todayPlan.trim().length > 0 &&
        reportContent.issueKeywords &&
        reportContent.issueKeywords.length >= requiredKeywordCount &&
        reportContent.issueDescription &&
        reportContent.issueDescription.length >= minimumIssueDescriptionLength,
    };
  
    // 外部モジュールの検証を呼び出し、結果を業務判定に組み込む
    const externalValidationInput = {
      reporterId: engineerId,
      teamId: teamId,
      reportDate: new Date().toISOString(),
      yesterdayAccomplishment: reportContent.yesterdayAccomplishment || "",
      todayPlan: reportContent.todayPlan,
      issueDescription: reportContent.issueDescription || "",
      issuePriority: "normal",
      issueKeywords: reportContent.issueKeywords || [],
    };
  
    const externalValidation = validateReportSubmission(externalValidationInput);
    const externalValidationPassed = externalValidation && externalValidation.isValid !== false;
  
    // 形式統一度を計算
    const formatComplianceScore = calculateFormatComplianceScore(
      reportContent,
      requiredKeywordCount,
      minimumIssueDescriptionLength
    );
  
    // 操作スキルスコアを計算
    const operationSkillScoreResult = calculateOperationSkillScore({
      engineerId,
      initialReportData: {
        reportId,
        submissionTimestamp: new Date().toISOString(),
        operationStepsCompleted: requiredFieldsCheckResult.isValid ? 3 : 1,
        errorOccurrenceCount: requiredFieldsCheckResult.isValid ? 0 : 2,
      },
      trainingCompletionDate: trainingCompletionDate.toISOString(),
      evaluationCriteria: {
        passingScore: minimumQualityScoreThreshold,
      },
    });
  
    // フィードバック項目の生成
    const feedbackItems: FeedbackItem[] = [];
  
    if (!reportContent.yesterdayAccomplishment?.trim()) {
      feedbackItems.push({
        fieldName: "昨日の実績",
        evaluationLevel: "POOR",
        improvementInstruction: "昨日実施した内容を具体的に記入してください",
      });
    }
  
    if (!reportContent.todayPlan?.trim()) {
      feedbackItems.push({
        fieldName: "本日の予定",
        evaluationLevel: "POOR",
        improvementInstruction: "本日の予定を具体的に記入してください",
      });
    }
  
    if (
      !reportContent.issueKeywords ||
      reportContent.issueKeywords.length < requiredKeywordCount
    ) {
      feedbackItems.push({
        fieldName: "課題キーワード",
        evaluationLevel: "FAIR",
        improvementInstruction: `最低${requiredKeywordCount}個のキーワードを入力してください`,
      });
    }
  
    if (
      !reportContent.issueDescription ||
      reportContent.issueDescription.length < minimumIssueDescriptionLength
    ) {
      feedbackItems.push({
        fieldName: "課題説明",
        evaluationLevel: "POOR",
        improvementInstruction: `課題説明は${minimumIssueDescriptionLength}文字以上で記入してください`,
      });
    }
  
    if (formatComplianceScore < 70) {
      feedbackItems.push({
        fieldName: "形式",
        evaluationLevel: "FAIR",
        improvementInstruction: "報告フォーマットに従って記入してください",
      });
    }
  
    // 総合判定：外部検証結果も組み込む
    const isQualityPassed =
      requiredFieldsCheckResult.isValid &&
      externalValidationPassed &&
      operationSkillScoreResult.skillScore >= minimumQualityScoreThreshold &&
      formatComplianceScore >= 70;
  
    const validationStatus = isQualityPassed ? "PASSED" : "FAILED";
  
    return {
      validationStatus,
      requiredFieldsCheckResult,
      formatComplianceScore,
      operationSkillScore: operationSkillScoreResult.skillScore,
      feedbackItems,
    };
  }
  
  function calculateFormatComplianceScore(
    reportContent: ReportContent,
    requiredKeywordCount: number,
    minimumIssueDescriptionLength: number
  ): number {
    let score = 100;
  
    if (!reportContent.yesterdayAccomplishment?.trim()) {
      score -= 25;
    }
  
    if (!reportContent.todayPlan?.trim()) {
      score -= 25;
    }
  
    if (
      !reportContent.issueKeywords ||
      reportContent.issueKeywords.length < requiredKeywordCount
    ) {
      score -= 20;
    }
  
    if (
      !reportContent.issueDescription ||
      reportContent.issueDescription.length < minimumIssueDescriptionLength
    ) {
      score -= 30;
    }
  
    return Math.max(0, score);
  }
  return { validateInitialReportQuality };
})();
export const validateInitialReportQuality = __aivicBundle_8_validateInitialReportQuality.validateInitialReportQuality;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateInitialReportQuality */

