/* AIVIC_FUNCTION_BUNDLE_START owner=calculateSubmissionRate exports=calculateSubmissionRate */
const __aivicBundle_12_calculateSubmissionRate = (() => {
  async function calculateSubmissionRate(
    input: SubmissionRateCalculationInput
  ): Promise<SubmissionRateResult> {
    const teamId = input.teamId || "";
    const evaluationStartDate = input.evaluationStartDate || new Date();
    const evaluationEndDate = input.evaluationEndDate || new Date();
  
    // Default requesterId for access control check
    const requesterId = "system";
  
    // Check access permission
    const permissionResult = await judgeAccessPermission({
      userId: requesterId,
      resourceType: "report",
      operation: "view",
      targetTeamId: teamId,
      confidentialityLevel: "internal",
    });
  
    if (!permissionResult.isPermitted) {
      return {
        submissionRate: 0,
        isAchieved90Percent: false,
      };
    }
  
    // Collect submission data for each day in the evaluation period
    let totalSubmitted = 0;
    let totalMembers = 0;
    const memberSubmissionMap = new Map<string, boolean>();
  
    const currentDate = new Date(evaluationStartDate);
    while (currentDate <= evaluationEndDate) {
      const reportDateStr = currentDate.toISOString().split("T")[0];
  
      const submissionStatus = await getSubmissionStatus({
        teamId,
        reportDate: reportDateStr,
        requesterId,
      });
  
      // Track unique members and their submission status
      submissionStatus.submittedMembers.forEach((member) => {
        memberSubmissionMap.set(member.memberId, true);
      });
  
      submissionStatus.unsubmittedMembers.forEach((member) => {
        if (!memberSubmissionMap.has(member.memberId)) {
          memberSubmissionMap.set(member.memberId, false);
        }
      });
  
      currentDate.setDate(currentDate.getDate() + 1);
    }
  
    // Calculate submission rate
    totalMembers = memberSubmissionMap.size;
    totalSubmitted = Array.from(memberSubmissionMap.values()).filter(
      (submitted) => submitted === true
    ).length;
  
    const submissionRate =
      totalMembers > 0 ? Math.round((totalSubmitted / totalMembers) * 100) : 0;
    const isAchieved90Percent = submissionRate >= 90;
  
    return {
      submissionRate,
      isAchieved90Percent,
    };
  }
  return { calculateSubmissionRate };
})();
export const calculateSubmissionRate = __aivicBundle_12_calculateSubmissionRate.calculateSubmissionRate;
